from flask import Flask, render_template, request, jsonify
from cerebras.cloud.sdk import Cerebras

app = Flask(__name__)

# Initialize Cerebras client with API key from environment variable
client = Cerebras(api_key=os.environ.get("CEREBRAS_API_KEY"))

@app.route("/")
def index():
    return render_template("index.html")

@app.route("/chat", methods=["POST"])
def chat():
    from flask import Response
    import json

    user_message = request.json.get("message")
    if not user_message:
        return jsonify({"error": "Nincs üzenet megadva"}), 400

    def generate():
        try:
            # Call Cerebras API with optimized settings for maximum speed
            stream = client.chat.completions.create(
                messages=[
                    {
                        "role": "system",
                        "content": "Rövid, pontos válasz magyarul."
                    },
                    {
                        "role": "user",
                        "content": user_message
                    }
                ],
                model="llama-4-scout-17b-16e-instruct",
                stream=True,
                max_completion_tokens=512,
                temperature=0.1,
                top_p=0.5
            )

            # Stream each chunk as it arrives
            for chunk in stream:
                delta = chunk.choices[0].delta.content
                if delta:
                    yield f"data: {json.dumps({'chunk': delta})}\n\n"

            yield f"data: {json.dumps({'done': True})}\n\n"

        except Exception as e:
            yield f"data: {json.dumps({'error': str(e)})}\n\n"

    return Response(generate(), mimetype='text/plain')

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=5000, debug=True)


