import time
from functools import wraps

def measure_time(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        start_time = time.time()
        result = f(*args, **kwargs)
        end_time = time.time()
        print(f"{f.__name__} took {end_time - start_time:.2f} seconds")
        return result
    return decorated_function

