Optimalizált Nginx beállítások[6][7]:

```nginx
# /etc/nginx/sites-available/jaded-light
server {
    listen 80;
    listen [::]:80;
    server_name your-domain.com 

    # Redirect HTTP to HTTPS
    return 301 
}

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name your-domain.com 

    # SSL Configuration
    ssl_certificate /path/to/certificate.crt;
    ssl_certificate_key /path/to/private.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers ECDHE-RSA-AES128-GCM-SHA256:ECDHE-RSA-AES256-GCM-SHA384;
    ssl_prefer_server_ciphers off;

    # Security headers
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

    # Gzip compression
    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_proxied any;
    gzip_comp_level 6;
    gzip_types
        text/plain
        text/css
        text/xml
        text/javascript
        application/json
        application/javascript
        application/xml+rss
        application/atom+xml
        image/svg+xml;

    # Brotli compression (if available)
    brotli on;
    brotli_comp_level 6;
    brotli_types
        text/plain
        text/css
        application/json
        application/javascript
        text/xml
        application/xml
        application/xml+rss
        text/javascript;

    # Static files optimization
    location /static/ {
        alias /path/to/your/app/static/;
        expires 1y;
        add_header Cache-Control "public, immutable";
        add_header X-Content-Type-Options nosniff;

        # Enable HTTP/2 server push for critical resources
        location ~* \.(css|js)$ {
            add_header Link "</static/css/main.css>; rel=preload; as=style" always;
            add_header Link "</static/js/main.js>; rel=preload; as=script" always;
        }

        # Optimize image delivery
        location ~* \.(jpg|jpeg|png|gif|webp|avif)$ {
            add_header Vary Accept;
        }
    }

    # Chat endpoint - streaming optimized
    location /chat {
        proxy_pass 
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Streaming optimizations
        proxy_buffering off;
        proxy_cache off;
        proxy_read_timeout 60s;
        proxy_send_timeout 60s;

        # Rate limiting
        limit_req zone=api burst=20 nodelay;
    }

    # Main application
    location / {
        proxy_pass 
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Caching for main page
        proxy_cache main_cache;
        proxy_cache_valid 200 5m;
        proxy_cache_key $scheme$request_method$host$request_uri;
    }

    # Health check endpoint
    location /health {
        access_log off;
        return 200 "healthy\n";
        add_header Content-Type text/plain;
    }
}

# Rate limiting zones
http {
    limit_req_zone $binary_remote_addr zone=api:10m rate=60r/m;
    limit_req_zone $binary_remote_addr zone=general:10m rate=10r/s;

    # Proxy cache configuration
    proxy_cache_path /var/cache/nginx/main levels=1:2 keys_zone=main_cache:10m max_size=100m;

    # Connection optimizations
    keepalive_timeout 65;
    keepalive_requests 1000;
    send_timeout 60;
    client_body_timeout 60;
    client_header_timeout 60;

    # Buffer optimizations
    client_body_buffer_size 128k;
    client_max_body_size 1m;
    client_header_buffer_size 1k;
    large_client_header_buffers 4 4k;

    # Worker optimizations
    worker_processes auto;
    worker_connections 1024;
    multi_accept on;
    use epoll;
}
