```python
# monitoring.py
import time
import psutil
import os
from functools import wraps
from flask import request, g

class PerformanceMonitor:
    def __init__(self):
        self.metrics = {
            'requests_total': 0,
            'requests_success': 0,
            'requests_error': 0,
            'avg_response_time': 0,
            'memory_usage': 0,
            'cpu_usage': 0
        }
        self.process = psutil.Process(os.getpid())

    def track_request(self, f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            start_time = time.time()
            g.start_time = start_time

            try:
                result = f(*args, **kwargs)
                self.metrics['requests_success'] += 1
                return result
            except Exception as e:
                self.metrics['requests_error'] += 1
                raise
            finally:
                end_time = time.time()
                response_time = (end_time - start_time) * 1000  # ms

                self.metrics['requests_total'] += 1

                # Update average response time
                total_requests = self.metrics['requests_total']
                current_avg = self.metrics['avg_response_time']
                self.metrics['avg_response_time'] = (
                    (current_avg * (total_requests - 1) + response_time) / total_requests
                )

                # Update system metrics
                self.metrics['memory_usage'] = self.process.memory_info().rss / 1024 / 1024  # MB
                self.metrics['cpu_usage'] = self.process.cpu_percent()

                # Log slow requests
                if response_time > 1000:  # > 1 second
                    print(f"Slow request: {request.path} took {response_time:.2f}ms")

        return decorated_function

    def get_metrics(self):
        return self.metrics.copy()

# Használat a main.py-ban
