## Cerebras API Optimalizálások

### Connection Pooling és Retry Logic

```python
# cerebras_optimizer.py
import asyncio
import aiohttp
from tenacity import retry, stop_after_attempt, wait_exponential

class CerebrasOptimizer:
    def __init__(self, api_key, max_connections=10):
        self.api_key = api_key
        self.base_url = ""
        self.session = None
        self.max_connections = max_connections

    async def __aenter__(self):
        connector = aiohttp.TCPConnector(
            limit=self.max_connections,
            limit_per_host=self.max_connections,
            keepalive_timeout=30,
            enable_cleanup_closed=True
        )

        timeout = aiohttp.ClientTimeout(total=30, connect=5)

        self.session = aiohttp.ClientSession(
            connector=connector,
            timeout=timeout,
            headers={
                'Authorization': f'Bearer {self.api_key}',
                'Content-Type': 'application/json'
            }
        )
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        if self.session:
            await self.session.close()

    @retry(
        stop=stop_after_attempt(3),
        wait=wait_exponential(multiplier=1, min=4, max=10)
    )
    async def chat_completion(self, messages, **kwargs):
        payload = {
            'model': 'llama-4-scout-17b-16e-instruct',
            'messages': messages,
            'stream': True,
            'max_completion_tokens': kwargs.get('max_tokens', 256),
            'temperature': kwargs.get('temperature', 0.1),
            'top_p': kwargs.get('top_p', 0.5)
        }

        async with self.session.post(
            f"{self.base_url}/chat/completions",
            json=payload
        ) as response:
            response.raise_for_status()

            async for line in response.content:
                if line.startswith(b'data: '):
                    yield line.decode('utf-8')[6:]  # Remove 'data: ' prefix
