```python
import os
import json
import hashlib
import time
from functools import wraps
from flask import Flask, render_template, request, jsonify, Response, g
from cerebras.cloud.sdk import Cerebras

app = Flask(__name__)

# Redis import (opcionális)
try:
    import redis
    redis_client = redis.Redis(
        host=os.environ.get('REDIS_HOST', 'localhost'),
        port=int(os.environ.get('REDIS_PORT', 6379)),
        db=0,
        decode_responses=True,
        socket_connect_timeout=5,
        socket_timeout=5,
        retry_on_timeout=True
    )
    redis_client.ping()
    print("Redis kapcsolat sikeres")
except Exception as e:
    print(f"Redis nem elérhető: {e}")
    redis_client = None

# Cerebras client
client = Cerebras(
    api_key=os.environ.get("CEREBRAS_API_KEY")
)

# Performance monitoring
class PerformanceMonitor:
    def __init__(self):
        self.metrics = {
            'requests_total': 0,
            'requests_success': 0,
            'requests_error': 0,
            'avg_response_time': 0
        }

    def track_request(self, f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            start_time = time.time()
            g.start_time = start_time

            try:
                result = f(*args, **kwargs)
                self.metrics['requests_success'] += 1
                return result
            except Exception as e:
                self.metrics['requests_error'] += 1
                raise
            finally:
                end_time = time.time()
                response_time = (end_time - start_time) * 1000

                self.metrics['requests_total'] += 1
                total_requests = self.metrics['requests_total']
                current_avg = self.metrics['avg_response_time']
                self.metrics['avg_response_time'] = (
                    (current_avg * (total_requests - 1) + response_time) / total_requests
                )

                if response_time > 1000:
                    print(f"Lassú kérés: {request.path} - {response_time:.2f}ms")

        return decorated_function

monitor = PerformanceMonitor()

# Cache kulcs generálás
def get_cache_key(message):
    return f"cerebras_response:{hashlib.md5(message.encode()).hexdigest()}"

# Gyakori válaszok
COMMON_RESPONSES = {
    "hello": "Szia! Hogyan segíthetek?",
    "hi": "Üdvözlöm! Miben segíthetek?",
    "help": "Természetesen segítek! Mit szeretnél tudni?",
    "szia": "Szia! Mit szeretnél megkérdezni?",
    "hello": "Helló! Miben segíthetek?",
    "köszönöm": "Szívesen! Van még kérdésed?",
    "köszi": "Nincs mit! Segíthetek még valamiben?"
}

@app.route("/")
def index():
    return render_template("index.html")

@app.route("/health")
def health():
    return jsonify({"status": "healthy", "metrics": monitor.metrics})

@app.route("/chat", methods=["POST"])
@monitor.track_request
def chat():
    user_message = request.json.get("message", "").strip()
    if not user_message:
        return jsonify({"error": "Nincs üzenet megadva"}), 400

    # Gyors válasz gyakori kérdésekre
    normalized_message = user_message.lower()
    if normalized_message in COMMON_RESPONSES:
        def quick_response():
            response = COMMON_RESPONSES[normalized_message]
            yield f"data: {json.dumps({'chunk': response})}\n\n"
            yield f"data: {json.dumps({'done': True})}\n\n"
        return Response(quick_response(), mimetype='text/plain')

    # Cache ellenőrzés
    cache_key = get_cache_key(user_message)
    if redis_client:
        try:
            cached_response = redis_client.get(cache_key)
            if cached_response:
                def serve_cached():
                    # Streaming cache-elt válasz
                    words = cached_response.split(' ')
                    for i, word in enumerate(words):
                        if i < len(words) - 1:
                            yield f"data: {json.dumps({'chunk': word + ' '})}\n\n"
                        else:
                            yield f"data: {json.dumps({'chunk': word})}\n\n"
                        time.sleep(0.02)  # Természetes typing effect
                    yield f"data: {json.dumps({'done': True})}\n\n"
                return Response(serve_cached(), mimetype='text/plain')
        except Exception as e:
            print(f"Cache olvasási hiba: {e}")

    def generate():
        try:
            full_response = ""

            stream = client.chat.completions.create(
                messages=[
                    {
                        "role": "system",
                        "content": "Válaszolj röviden és pontosan magyarul. Maximum 3 mondat."
                    },
                    {
                        "role": "user",
                        "content": user_message
                    }
                ],
                model="llama-4-scout-17b-16e-instruct",
                stream=True,
                max_completion_tokens=300,
                temperature=0.1,
                top_p=0.5,
                frequency_penalty=0.1,
                presence_penalty=0.1
            )

            chunk_buffer = ""
            chunk_count = 0

            for chunk in stream:
                if hasattr(chunk.choices[0].delta, 'content') and chunk.choices[0].delta.content:
                    delta = chunk.choices[0].delta.content
                    full_response += delta
                    chunk_buffer += delta
                    chunk_count += 1

                    # Batch küldés minden 3. chunk után
                    if chunk_count >= 3 or any(punct in delta for punct in '.!?'):
                        yield f"data: {json.dumps({'chunk': chunk_buffer})}\n\n"
                        chunk_buffer = ""
                        chunk_count = 0

            # Maradék küldése
            if chunk_buffer:
                yield f"data: {json.dumps({'chunk': chunk_buffer})}\n\n"

            # Cache-be mentés
            if redis_client and full_response.strip():
                try:
                    redis_client.setex(cache_key, 3600, full_response.strip())
                except Exception as e:
                    print(f"Cache írási hiba: {e}")

            yield f"data: {json.dumps({'done': True})}\n\n"

        except Exception as e:
            error_msg = f"Hiba történt: {str(e)}"
            yield f"data: {json.dumps({'error': error_msg})}\n\n"

    return Response(generate(), mimetype='text/plain')

@app.after_request
def after_request(response):
    response.headers['X-Content-Type-Options'] = 'nosniff'
    response.headers['X-Frame-Options'] = 'DENY'
    response.headers['X-XSS-Protection'] = '1; mode=block'

    if request.endpoint == 'chat':
        response.headers['Cache-Control'] = 'no-cache, no-store, must-revalidate'
        response.headers['Pragma'] = 'no-cache'
        response.headers['Expires'] = '0'
    else:
        response.headers['Cache-Control'] = 'public, max-age=31536000'

    return response

if __name__ == "__main__":
    app.run(host='0.0.0.0', port=5000, debug=False, threaded=True)
