            font-size: 3rem;
            margin-bottom: 1rem;
            opacity: 0.5;
        }

        .empty-state-text {
            font-size: 1.1rem;
            color: rgba(255, 255, 255, 0.7);
        }

        @media (max-width: 768px) {
            .header {
                padding: 2rem 1rem 1.5rem;
            }

            .title {
                font-size: 2.5rem;
            }

            .subtitle {
                font-size: 1.1rem;
            }

            .chat-area {
                padding: 1rem;
            }

            .input-area {
                padding: 1rem;
            }

            .message-content {
                max-width: 85%;
                font-size: 0.95rem;
            }
        }

        @media (max-width: 480px) {
            .title {
                font-size: 2rem;
            }

            .message-content {
                max-width: 90%;
            }
        }
    </style>
</head>
<body>
    <div class="app-container">
        <header class="header">
            <h1 class="title">JADED light</h1>
            <p class="subtitle">Intelligens válaszok, pillanatok alatt</p>
        </header>

        <main class="chat-area" id="chatArea">
            <div class="empty-state" id="emptyState">
                <div class="empty-state-icon">💬</div>
                <div class="empty-state-text">Kezdj el beszélgetni egy üzenet küldésével</div>
            </div>
        </main>

        <footer class="input-area">
            <div class="input-container">
                <textarea 
                    class="input-field" 
                    id="messageInput" 
                    placeholder="Írj egy üzenetet..."
                    rows="1"
                    autocomplete="off"
                    maxlength="500"
                ></textarea>
                <button class="send-button" id="sendButton" type="button" aria-label="Üzenet küldése">
                    <span class="send-icon">➤</span>
                    <span class="loading-spinner" style="display: none;"></span>
                </button>
            </div>
        </footer>
    </div>

    <script>
        class OptimizedChatApp {
            constructor() {
                this.chatArea = document.getElementById('chatArea');
                this.messageInput = document.getElementById('messageInput');
                this.sendButton = document.getElementById('sendButton');
                this.emptyState = document.getElementById('emptyState');
                this.sendIcon = this.sendButton.querySelector('.send-icon');
                this.loadingSpinner = this.sendButton.querySelector('.loading-spinner');

                this.isLoading = false;
                this.messageCount = 0;
                this.messageCache = new Map();
                this.debounceTimer = null;
                this.controller = null;

                this.init();
            }

            init() {
                this.sendButton.addEventListener('click', this.handleSendMessage.bind(this), { passive: true });
                this.messageInput.addEventListener('keydown', this.handleKeyDown.bind(this), { passive: false });
                this.messageInput.addEventListener('input', this.handleInput.bind(this), { passive: true });
                this.messageInput.addEventListener('paste', this.handlePaste.bind(this), { passive: true });

                document.addEventListener('visibilitychange', this.handleVisibilityChange.bind(this));

                this.messageInput.focus();
            }

            handleKeyDown(e) {
                if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    this.handleSendMessage();
                }
            }

            handleInput() {
                clearTimeout(this.debounceTimer);
                this.debounceTimer = setTimeout(() => {
                    this.autoResize();
                }, 16);
            }

            handlePaste(e) {
                setTimeout(() => {
                    const content = this.messageInput.value;
                    if (content.length > 500) {
                        this.messageInput.value = content.substring(0, 500);
                        this.autoResize();
                    }
                }, 0);
            }

            handleVisibilityChange() {
                if (document.hidden && this.controller) {
                    this.controller.abort();
                    this.setLoading(false);
                }
            }

            autoResize() {
                this.messageInput.style.height = 'auto';
                this.messageInput.style.height = Math.min(this.messageInput.scrollHeight, 128) + 'px';
            }

            hideEmptyState() {
                if (this.messageCount === 0 && this.emptyState) {
                    this.emptyState.style.display = 'none';
                    this.messageCount++;
                }
            }

            createMessage(content, type) {
                const messageDiv = document.createElement('div');
                messageDiv.className = `message ${type}-message`;
                messageDiv.setAttribute('role', 'article');
                messageDiv.setAttribute('aria-live', type === 'bot' ? 'polite' : 'off');

                const contentDiv = document.createElement('div');
                contentDiv.className = 'message-content';

                if (type === 'user') {
                    contentDiv.textContent = content;
                } else {
                    contentDiv.innerHTML = '';
                }

                messageDiv.appendChild(contentDiv);
                return messageDiv;
            }

            createTypingIndicator() {
                const typingDiv = document.createElement('div');
                typingDiv.className = 'typing-indicator';
                typingDiv.setAttribute('aria-label', 'AI válaszol...');
                typingDiv.innerHTML = `
                    <div class="typing-dot"></div>
                    <div class="typing-dot"></div>
                    <div class="typing-dot"></div>
                `;
                return typingDiv;
            }

            appendMessage(element) {
                this.hideEmptyState();

                const fragment = document.createDocumentFragment();
                fragment.appendChild(element);
                this.chatArea.appendChild(fragment);

                this.smoothScrollToBottom();
            }

            smoothScrollToBottom() {
                if ('requestIdleCallback' in window) {
                    requestIdleCallback(() => {
                        this.chatArea.scrollTo({
                            top: this.chatArea.scrollHeight,
                            behavior: 'smooth'
                        });
                    });
                } else {
                    requestAnimationFrame(() => {
                        this.chatArea.scrollTo({
                            top: this.chatArea.scrollHeight,
                            behavior: 'smooth'
                        });
                    });
                }
            }

            setLoading(loading) {
                this.isLoading = loading;
                this.sendButton.disabled = loading;
                this.messageInput.disabled = loading;

                if (loading) {
                    this.sendIcon.style.display = 'none';
                    this.loadingSpinner.style.display = 'block';
                    this.sendButton.setAttribute('aria-label', 'Küldés folyamatban...');
                } else {
                    this.sendIcon.style.display = 'block';
                    this.loadingSpinner.style.display = 'none';
                    this.sendButton.setAttribute('aria-label', 'Üzenet küldése');
                }
            }

            async handleSendMessage() {
                const message = this.messageInput.value.trim();
                if (!message || this.isLoading) return;

                if (this.messageCache.has(message)) {
                    const cachedResponse = this.messageCache.get(message);
                    this.displayCachedMessage(message, cachedResponse);
                    return;
                }

                this.appendMessage(this.createMessage(message, 'user'));
                this.messageInput.value = '';
                this.autoResize();

                const typingIndicator = this.createTypingIndicator();
                this.appendMessage(typingIndicator);

                this.setLoading(true);

                this.controller = new AbortController();

                try {
                    const response = await fetch('/chat', {
                        method: 'POST',
                        headers: { 
                            'Content-Type': 'application/json',
                            'Accept': 'text/plain'
                        },
                        body: JSON.stringify({ message }),
                        signal: this.controller.signal
                    });

                    if (!response.ok) {
                        throw new Error(`HTTP error! status: ${response.status}`);
                    }

                    this.chatArea.removeChild(typingIndicator);

                    const botMessage = this.createMessage('', 'bot');
                    const botContent = botMessage.querySelector('.message-content');
                    this.appendMessage(botMessage);

                    const reader = response.body.getReader();
                    const decoder = new TextDecoder();
                    let botResponse = '';
                    let buffer = '';
                    let chunkCount = 0;

                    while (true) {
                        const { done, value } = await reader.read();
                        if (done) break;

                        buffer += decoder.decode(value, { stream: true });
                        const lines = buffer.split('\n');
                        buffer = lines.pop() || '';

                        for (const line of lines) {
                            if (line.trim().startsWith('data: ')) {
                                try {
                                    const data = JSON.parse(line.slice(6));
                                    if (data.chunk) {
                                        botResponse += data.chunk;

                                        chunkCount++;
                                        if (chunkCount % 5 === 0) {
                                            botContent.textContent = botResponse;
                                            this.smoothScrollToBottom();
                                        }
                                    } else if (data.error) {
                                        botContent.textContent = `Hiba történt: ${data.error}`;
                                        break;
                                    } else if (data.done) {
                                        botContent.textContent = botResponse;
                                        this.smoothScrollToBottom();

                                        if (botResponse.trim()) {
                                            this.messageCache.set(message, botResponse.trim());
                                            if (this.messageCache.size > 50) {
                                                const firstKey = this.messageCache.keys().next().value;
                                                this.messageCache.delete(firstKey);
                                            }
                                        }
                                        break;
                                    }
                                } catch (e) {
                                    console.warn('JSON parsing error:', e);
                                }
                            }
                        }
                    }

                } catch (error) {
                    if (this.chatArea.contains(typingIndicator)) {
                        this.chatArea.removeChild(typingIndicator);
                    }

                    if (error.name !== 'AbortError') {
                        const errorMessage = error.message.includes('fetch') 
                            ? 'Kapcsolódási hiba történt. Kérlek, próbáld újra.' 
                            : `Hiba történt: ${error.message}`;
                        this.appendMessage(this.createMessage(errorMessage, 'bot'));
                    }
                } finally {
                    this.setLoading(false);
                    this.controller = null;
                    this.messageInput.focus();
                }
            }

            displayCachedMessage(userMessage, cachedResponse) {
                this.appendMessage(this.createMessage(userMessage, 'user'));
                this.messageInput.value = '';
                this.autoResize();

                const botMessage = this.createMessage('', 'bot');
                const botContent = botMessage.querySelector('.message-content');
                this.appendMessage(botMessage);

                let i = 0;
                const typeInterval = setInterval(() => {
                    if (i < cachedResponse.length) {
                        botContent.textContent = cachedResponse.substring(0, i + 1);
                        i++;
                        if (i % 10 === 0) this.smoothScrollToBottom();
                    } else {
                        clearInterval(typeInterval);
                        this.smoothScrollToBottom();
                    }
                }, 20);

                this.messageInput.focus();
            }
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => {
                new OptimizedChatApp();
            });
        } else {
            new OptimizedChatApp();
        }
    </script>
</body>
</html>
```

## 🐳 docker-compose.yml
```yaml
version: '3.8'

services:
  app:
    build: .
    restart: unless-stopped
    ports:
      - "5000:5000"
    environment:
      - CEREBRAS_API_KEY=${CEREBRAS_API_KEY}
      - REDIS_HOST=redis
      - REDIS_PORT=6379
      - FLASK_ENV=production
    depends_on:
      - redis
    networks:
      - app-network

  redis:
    image: redis:7-alpine
    restart: unless-stopped
    command: redis-server --maxmemory 128mb --maxmemory-policy allkeys-lru
    volumes:
      - redis_data:/data
    networks:
      - app-network

volumes:
  redis_data:

networks:
  app-network:
    driver: bridge
```

## 🐳 Dockerfile
```dockerfile
FROM python:3.11-slim

WORKDIR /app

# Install system dependencies
RUN apt-get update && apt-get install -y \
    gcc \
    && rm -rf /var/lib/apt/lists/*

# Copy requirements and install Python dependencies
COPY requirements.txt .
RUN pip install --no-cache-dir --upgrade pip && \
    pip install --no-cache-dir -r requirements.txt

# Copy application code
COPY . .

# Create non-root user
RUN groupadd -r appuser && useradd -r -g appuser appuser
RUN chown -R appuser:appuser /app
USER appuser

# Health check
HEALTHCHECK --interval=30s --timeout=10s --start-period=5s --retries=3 \
    CMD curl -f  || exit 1

EXPOSE 5000

CMD ["gunicorn", "--config", "gunicorn_config.py", "main:app"]
```

